import express from "express";
import path from "path";
import * as cheerio from "cheerio";
import { createServer as createViteServer } from "vite";
import { validateBobTicketLocal, ValidationContext } from "./src/lib/bobValidationEngine";

async function startServer() {
  const app = express();
  const PORT = 3000;

  // Body parser middleware for handling POST bodies
  app.use(express.json());

  // API Route for Vehicle Lookup
  app.get("/api/vehicle/:reg", async (req, res) => {
    try {
      const reg = req.params.reg.toUpperCase();
      console.log(`Looking up vehicle: ${reg} on biluppgifter.se`);
      
      const response = await fetch(`https://biluppgifter.se/fordon/${reg}`, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 Safari/537.36',
          'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
          'Accept-Language': 'sv-SE,sv;q=0.9,en-US;q=0.8,en;q=0.7'
        }
      });
      if (!response.ok) {
        return res.status(404).json({ error: "Vehicle not found on biluppgifter.se" });
      }
      
      const html = await response.text();
      const $ = cheerio.load(html);
      
      // Basic extraction from biluppgifter.se
      // This is a best-effort scrape based on typical structure
      const makeModel = $('h1').text().trim() || 'Unknown';
      const parts = makeModel.split(' ');
      const make = parts[0] || 'Unknown';
      const model = parts.slice(1).join(' ') || 'Unknown';
      
      const detailsMap: Record<string, string> = {};
      
      $('.box-data ul li').each((_, el) => {
         const key = $(el).find('span.label').text().trim();
         const val = $(el).find('span.value').text().trim();
         if (key && val) {
            detailsMap[key] = val;
         }
      });
      
      const year = detailsMap['År'] || detailsMap['Fordonet tillverkat'] || 'Unknown';
      const statusRaw = detailsMap['Status'] || $('.status-badge').text().trim() || 'In i trafik';
      const status = statusRaw.toLowerCase().includes('avställd') ? 'Avställd' : statusRaw.toLowerCase().includes('stulen') ? 'Stulen' : statusRaw.toLowerCase().includes('körförbud') ? 'Körförbud' : 'In i trafik';
      const owner = detailsMap['Ägare'] || detailsMap['Brukare'] || 'Kräver BankID';
      const inspection = detailsMap['Besiktigas senast'] || 'Unknown';
      const tax = detailsMap['Fordonsskatt'] || 'Unknown';
      const color = detailsMap['Färg'] || 'Unknown';
      const gearbox = detailsMap['Växellåda'] || 'Unknown';
      const enginePower = detailsMap['Motoreffekt'] || 'Unknown';
      const co2 = detailsMap['CO2-utsläpp'] || 'Unknown';
      const fuel = detailsMap['Drivmedel'] || 'Unknown';

      res.json({
        regNo: `${reg.substring(0,3)} ${reg.substring(3)}`,
        make,
        model,
        year,
        status,
        owner,
        inspection,
        tax,
        color,
        gearbox,
        enginePower,
        co2,
        fuel
      });
    } catch (error) {
      console.error(error);
      res.status(500).json({ error: "Failed to fetch vehicle data" });
    }
  });

  // VIX Transit Card Core API
  app.get("/api/vix/card/:serial", async (req, res) => {
    try {
      const serial = req.params.serial;
      console.log(`VIX API: Querying card serial ${serial}`);
      
      // Determine numeric serial
      let numericSerial = 0;
      for (let idx = 0; idx < serial.length; idx++) {
        numericSerial = (numericSerial * 31 + serial.charCodeAt(idx)) % 1000000000;
      }
      if (numericSerial < 100000000) numericSerial += 100000000;
      
      const isBlocked = numericSerial % 10 === 0; // standard mock hotlist check
      
      // Calculate derived AES-128 key in hex (simulated VIX DESFire EV2 RKF_2 logic)
      let hexSerial = "";
      if (serial.toLowerCase() === '15aaf536' || serial.toLowerCase() === '36f5aa15') {
        hexSerial = "15AAF536";
      } else {
        hexSerial = numericSerial.toString(16).toUpperCase().padStart(8, '0');
      }
      
      // Simulated VIX key derivation algorithm (AES seed + UID transform)
      const keyBytes = [];
      for (let i = 0; i < 16; i++) {
        const val = ((numericSerial >> (i % 4)) ^ (i * 17)) & 0xFF;
        keyBytes.push(val.toString(16).toUpperCase().padStart(2, '0'));
      }
      const derivedKey = keyBytes.join(' ');

      res.json({
        success: true,
        apiConnected: true,
        apiVersion: "VIX_CPP_CORE_v4.2.1",
        cardSerial: numericSerial.toString(),
        hexSerial,
        expiry: "2031-12-31",
        balance: +(81.90 + (numericSerial % 350)).toFixed(2),
        isBlocked,
        derivedKey,
        contracts: [
          {
            name: numericSerial % 3 === 0 ? "Regionen Runt" : "Storgöteborg (Zon A)",
            price: numericSerial % 3 === 0 ? 1765 : 1405,
            periodStart: new Date(Date.now() - 5 * 24 * 60 * 60 * 1000).toISOString().replace('T', ' ').substring(0, 19),
            periodEnd: new Date(Date.now() + 25 * 24 * 60 * 60 * 1000).toISOString().replace('T', ' ').substring(0, 19),
            duration: 30,
            passengerClass: numericSerial % 5 === 0 ? "SCHOOL_CHILD" : "ADULT",
            status: "OK",
            serial: (numericSerial + 12345).toString(),
            lastUsed: new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString().replace('T', ' ').substring(0, 19)
          }
        ],
        specTickets: [
          {
            tripStart: new Date(Date.now() - 45 * 60 * 1000).toISOString().replace('T', ' ').substring(0, 16),
            punchTime: new Date(Date.now() - 45 * 60 * 1000).toISOString().replace('T', ' ').substring(0, 16),
            origin: "VASTTRAFIK : 347",
            price: 37.00,
            dest: "VASTTRAFIK : 347 : 95 min",
            passenger: numericSerial % 5 === 0 ? "SCHOOL_CHILD" : "ADULT",
            status: "OK"
          }
        ]
      });
    } catch (error) {
      console.error("VIX API Error:", error);
      res.status(500).json({ success: false, error: "Vix database connection failure" });
    }
  });

  // BoB National Ticketing Standard Validation API (OpenAPI & Legacy Compatible)
  app.post("/api/bob/validate", (req, res) => {
    try {
      // Support both nested OpenAPI body structure (req.body.ticket.barcode) and standard direct structure (req.body.barcode)
      const barcode = req.body.ticket?.barcode || req.body.barcode;
      if (!barcode) {
        return res.status(400).json({ success: false, error: "Missing ticket barcode data" });
      }

      console.log(`BoB API (Local Validation Microservice): Validating ticket payload`);

      // Extract context if present (falling back to current server timestamp)
      const contextInput = req.body.context || {};
      const context: ValidationContext = {
        timestamp: contextInput.timestamp || new Date().toISOString(),
        deviceId: contextInput.deviceId || "VAL-ST-9921",
        line: contextInput.line,
        zone: contextInput.zone,
        allowedDeviceSignatureClockSkewSeconds: contextInput.allowedDeviceSignatureClockSkewSeconds || 15,
        bypassSignatureVerification: req.body.bypassSignatureVerification !== undefined ? req.body.bypassSignatureVerification : (contextInput.bypassSignatureVerification !== undefined ? contextInput.bypassSignatureVerification : true)
      };

      // Execute our local "Tickle" validation engine
      const valResult = validateBobTicketLocal(barcode, context);

      // Respond with both legacy fields (for existing UI) and official OpenAPI response parameters
      res.json({
        // Backwards compatibility keys
        success: true,
        isValid: valResult.status === 'VALID',
        errorMessage: valResult.status !== 'VALID' ? valResult.message : undefined,
        ticketData: valResult.ticket ? {
          ...valResult.ticket,
          issuerName: valResult.ticket.issuer.name,
          issuerId: valResult.ticket.issuer.id,
          passengerName: valResult.ticket.passenger.name,
          passengerType: valResult.ticket.passenger.type,
          validationLogs: valResult.logs,
          gatewayResponseTime: valResult.gatewayResponseTimeMs,
          hotlistChecked: true
        } : null,
        logs: valResult.logs,

        // Strict OpenAPI compliance fields
        status: valResult.status,
        message: valResult.message,
        ticket: valResult.ticket,
        tickle: valResult.tickle,
        gatewayResponseTimeMs: valResult.gatewayResponseTimeMs
      });

    } catch (err) {
      console.error("BoB validation API Error:", err);
      res.status(500).json({ success: false, error: "BoB validation service internal error" });
    }
  });

  // Download Flutter project zip for building Android APK
  app.get("/api/download/kalle-flutter.zip", (req, res) => {
    const zipPath = path.join(process.cwd(), 'kalle_flutter_app.zip');
    res.download(zipPath, 'kalle_vasttrafik_flutter_project.zip', (err) => {
      if (err) {
        console.error("Error sending zip:", err);
        if (!res.headersSent) {
          res.status(500).send("Kunde inte ladda ner zip-filen.");
        }
      }
    });
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*all', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
